import type { TabInlineBadgeProps } from "./tab/tab.types";

import { forwardRef } from "react";
import { InlineBadge } from "@components/inline-badge";
import { clsx } from "clsx";

import { TabClasses } from "./tab/tab.styles";

export const TabInlineBadge = forwardRef<HTMLDivElement, TabInlineBadgeProps>(
  ({ className, variant = "new", ...props }, ref) => {
    const inlineBadgeClasses = clsx(TabClasses.inlineBadge, className);

    return <InlineBadge ref={ref} className={inlineBadgeClasses} variant={variant} {...props} />;
  },
);

TabInlineBadge.displayName = "Tab.InlineBadge";
